package dev.starfold;

import net.minecraft.core.Direction;
import org.joml.Vector3d;
import org.junit.jupiter.api.Test;
import static dev.starfold.NativeHelmCommand.*;
import static org.junit.jupiter.api.Assertions.*;

class NativeHelmCommandTest {
    // tools/ship/rocket.py, body-local positions relative to a centre near (0,.5,0).
    private record Jet(Direction nozzle,Vector3d arm){}
    private static final Jet[] ROCKET={new Jet(Direction.EAST,new Vector3d(4,1,0)),new Jet(Direction.WEST,new Vector3d(-4,0,0)),new Jet(Direction.DOWN,new Vector3d(0,0,0)),new Jet(Direction.UP,new Vector3d(1,1,-1)),new Jet(Direction.UP,new Vector3d(1,1,1)),new Jet(Direction.NORTH,new Vector3d(-4,0,-2)),new Jet(Direction.SOUTH,new Vector3d(4,1,2)),new Jet(Direction.SOUTH,new Vector3d(-4,0,2)),new Jet(Direction.NORTH,new Vector3d(4,1,-2))};
    private static java.util.List<Integer> fired(int bits,boolean free){var result=new java.util.ArrayList<Integer>();for(int i=0;i<ROCKET.length;i++){var t=ROCKET[i];if(fires(bits,Direction.WEST,t.nozzle(),t.arm(),free))result.add(i);}return result;}
    @Test void starterKeysSelectExactlyTheirThrusters(){assertEquals(java.util.List.of(0),fired(FORWARD,false));assertEquals(java.util.List.of(1),fired(BACK,false));assertEquals(java.util.List.of(2),fired(UP,false));assertEquals(java.util.List.of(3,4),fired(DOWN,false));assertEquals(java.util.List.of(5,6),fired(LEFT,false));assertEquals(java.util.List.of(7,8),fired(RIGHT,false));assertTrue(fired(SPRINT,false).isEmpty());assertTrue(fired(0,false).isEmpty());}
    @Test void freeAttitudeADOnlyRollsAndDoesNotFire(){assertTrue(fired(LEFT,true).isEmpty());assertTrue(fired(RIGHT,true).isEmpty());assertEquals(java.util.List.of(0),fired(FORWARD|LEFT,true));assertEquals(1,roll(LEFT));assertEquals(-1,roll(RIGHT));}
    @Test void yawSignWorksForEveryForwardAndRejectsSideTranslation(){for(var f:new Direction[]{Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST}){var forward=new Vector3d(f.getStepX(),0,f.getStepZ());var right=new Vector3d(forward).cross(0,1,0);var leftPush=Direction.getNearest(-right.x,0,-right.z);assertTrue(fires(LEFT,f,leftPush.getOpposite(),new Vector3d(forward).mul(4),false));assertTrue(fires(LEFT,f,leftPush,new Vector3d(forward).mul(-4),false));assertFalse(fires(RIGHT,f,leftPush.getOpposite(),new Vector3d(forward).mul(4),false));assertFalse(fires(LEFT,f,leftPush.getOpposite(),new Vector3d(right).mul(2),false));assertFalse(fires(RIGHT,f,leftPush.getOpposite(),new Vector3d(right).mul(2),false));}}
    @Test void attitudeAxesFollowControllerPoseRatherThanPilotYaw(){var frame=NativeSpace.Frame.IDENTITY;var model=NativeSpaceTest.tilted();for(double yaw:new double[]{0,90,180,270}){double a=Math.toRadians(yaw);var f=new BentStripGeometry.Point(-Math.sin(a),0,Math.cos(a));var up=new BentStripGeometry.Point(0,1,0);var old=NativeSpaceServer.attitude(frame,model,0,NativeSpace.ORIGIN,false,true,yaw,.3,-.2,1,2);var current=NativeSpaceServer.attitude(frame,model,0,NativeSpace.ORIGIN,false,true,f,up,.3,-.2,1,2);assertEquals(old.x,current.x,1e-12);assertEquals(old.y,current.y,1e-12);assertEquals(old.z,current.z,1e-12);assertEquals(old.w,current.w,1e-12);var pose=new org.joml.Quaterniond().rotateXYZ(.4,.2,-.3);var fv=pose.transform(new Vector3d(f.x(),f.y(),f.z()));var uv=pose.transform(new Vector3d(0,1,0));var rotated=NativeSpaceServer.attitude(frame,model,0,NativeSpace.ORIGIN,false,true,new BentStripGeometry.Point(fv.x,fv.y,fv.z),new BentStripGeometry.Point(uv.x,uv.y,uv.z),.3,-.2,1,2);var expected=new org.joml.Quaterniond(pose).mul(old).mul(new org.joml.Quaterniond(pose).conjugate());assertEquals(expected.x,rotated.x,1e-12);assertEquals(expected.y,rotated.y,1e-12);assertEquals(expected.z,rotated.z,1e-12);assertEquals(expected.w,rotated.w,1e-12);}}
    @Test void commandCombinesWithRedstoneAndBoostNeedsHardware(){for(int redstone=0;redstone<=15;redstone++){assertEquals(redstone,effective(redstone,false));assertEquals(15,effective(redstone,true));}assertFalse(boosted(SPRINT,false));assertFalse(boosted(0,true));assertTrue(boosted(SPRINT,true));assertTrue(boosted(FORWARD|SPRINT,true));}
    @Test void inputLeaseRejectsFutureAndExpiredTicks(){assertFalse(fresh(10,9));assertTrue(fresh(10,10));assertTrue(fresh(10,15));assertFalse(fresh(10,16));assertFalse(fresh(Long.MIN_VALUE,0));}
    @Test void ownershipIsExclusiveMovesAtomicallyAndIsNotPersistent(){var p=new Pilots<String,String>();assertTrue(p.take("helm-a","alice"));assertFalse(p.take("helm-a","bob"));assertEquals("alice",p.owner("helm-a"));assertTrue(p.take("helm-b","bob"));assertFalse(p.take("helm-a","bob"));assertEquals("bob",p.owner("helm-b"));assertTrue(p.take("helm-c","alice"));assertNull(p.owner("helm-a"));assertEquals("alice",p.owner("helm-c"));p.release("helm-c");assertTrue(p.take("helm-c","bob"));assertNull(p.owner("helm-b"));p.clear();assertNull(p.owner("helm-c"));assertNull(new Pilots<String,String>().owner("helm-c"));}
}
